&- \left( 8 \sin \frac{5 \pi}{6} + 8 \sin \pi + 8 \sin \frac{7 \pi}{6} + 8 \sin \frac{4 \pi}{3} + 8 \sin \frac{3 \pi}{2} + 8 \sin \frac{5 \pi}{3} \right) \\
&= \boxed{16 + 16 \sqrt{3}}.
\end{align*}

