real parab (real x) {
  return(x^2);
}

draw(graph(parab,-2,2));
draw((1,-4)--(A + (1,2)));
draw((1,2)--(A + (-2,4)));
draw(A--B--N--cycle);

dot("$A$", A, S);
dot("$B$", B, SW);
dot("$N$", N, NE);
